matched.driver:
// Matched-start board-profile workloads using the production host and independent SRR.
// Focused wide prepared triangles exercise exact offset arithmetic on both
// axes. Their texture is uploaded on first use through the ordinary host.
#define main original_gpu_main
#include "main.cpp"
#undef main

namespace {

std::shared_ptr<const Image> patterned_texture(int width, int height, int pitch, std::uint16_t salt) {
    auto image = std::make_shared<Image>(width, height, pitch);
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            const auto mixed = static_cast<std::uint16_t>(
                salt ^ ((x * 7193 + y * 3989 + (x ^ y) * 127) & 0xFFFF));
            image->at(x, y) = (x + 3 * y) % 7 == 0 ? 0xf81f : mixed;
        }
    }
    return image;
}

Pass split_texture_pass() {
    // Stock packing puts the second base at HEAP+4, third at HEAP+76.
    // These legal word-aligned bases are off the physical 32-byte burst.
    const auto start = patterned_texture(2, 1, 4, 0x1597);
    const auto pitched = patterned_texture(16, 2, 36, 0x30a5);
    const auto wide = patterned_texture(32, 4, 68, 0x1d42);
    Pass pass;
    pass.target = 1;
    pass.clear_color = 0x1ca5;
    const auto sprite = [&](const std::shared_ptr<const Image>& image, Bounds bounds,
                            int sx, int sy, Bounds scissor, std::uint32_t depth) {
        RenderState state;
        state.texture = image;
        state.shade = ShadeMode::TextureReplace;
        state.color_key = 0xf81f;
        state.scissor = scissor;
        state.depth_func = DepthFunc::LessEqual;
        pass.primitives.emplace_back(Sprite{bounds, sx, sy, state, depth});
    };
    for (int y = 30; y < 192; y += 13) {
        // Second and third textures include the last allocated line (two and
        // four useful words respectively). Distinct depths expose key mistakes.
        sprite(start, {28, y, 30, y + 1}, 0, 0, Bounds{}, 0x52179a);
        sprite(pitched, {29, y, 34, y + 1}, 11, 1, {30, y, 34, y + 1}, 0x33945e);
        sprite(wide, {30, y, 37, y + 2}, 25, 2, {31, y, 37, y + 2}, 0x295b7c);
        sprite(pitched, {35, y + 1, 40, y + 2}, 11, 0, Bounds{}, 0x452c80);
    }
    return pass;
}

Pass locality_texture_pass(const std::shared_ptr<const Image>& image) {
    // Same screen and UV footprints for tiny/warm and large/contention cases.
    // 17 texels per horizontal pixel and 11 per scanline stay within the
    // supported vertex UV range. A small repeated footprint fits in four
    // lines; the far larger pitched image traverses all cache sets.
    RenderState state;
    state.shade = ShadeMode::TextureReplace;
    state.address_u = AddressMode::Repeat;
    state.address_v = AddressMode::Repeat;
    state.texture = image;
    state.scissor = {94, 76, 185, 166};
    const ScreenVertex a{90, 73, 0.42L, 1, -815.75L, -527.75L};
    const ScreenVertex b{186, 73, 0.42L, 1,  816.25L, -527.75L};
    const ScreenVertex c{186, 169, 0.42L, 1, 816.25L,  528.25L};
    const ScreenVertex d{90, 169, 0.42L, 1, -815.75L,  528.25L};
    const std::array<ScreenVertex, 3> first{{a, b, c}}, second{{a, c, d}};
    Pass pass;
    pass.target = 1;
    pass.clear_color = 0x2b04;
    for (const auto& vertices : {first, second}) {
        const auto triangle = setup_triangle(vertices, state);
        if (!triangle) throw std::runtime_error("expected the clipped benchmark triangle to draw");
        pass.primitives.emplace_back(*triangle);
    }
    return pass;
}

struct OffsetWorkload {
    Pass pass;
    int max_x_offset = 0, max_y_offset = 0;
    unsigned x_residues = 0, y_residues = 0;
};

OffsetWorkload wide_offset_triangles() {
    OffsetWorkload fixture;
    auto& pass = fixture.pass;
    pass.target = 1;
    pass.clear_color = 0x841;
    pass.clear_depth = 0xe7abc9;

    // An atlas small enough to fit the live texture cache isolates the long
    // plane walks while exercising q/U/V and first-use upload.
    const auto texture = patterned_texture(16, 16, 36, 0x89ab);
    for (int layer = 0; layer < 4; ++layer) {
        const auto k = static_cast<long double>(layer);
        RenderState state;
        state.texture = texture;
        state.shade = ShadeMode::TextureGouraudModulate;
        state.address_u = AddressMode::Repeat;
        state.address_v = AddressMode::Clamp;
        state.color_key = 0xf81f;
        state.depth_func = (layer & 1) ? DepthFunc::LessEqual : DepthFunc::Less;
        // Clipping shifts the RGB, perspective, and D24 anchors to every
        // modulo-four residue. Far tile origins still occupy aligned columns.
        state.scissor = {7 + layer, 5 + layer * 3, 638 - layer, 478 - layer};
        const ScreenVertex a{
            3 + k, 2 + k, 0.73L - k * 0.11L, 1.125L, -22.75L + k * 3,
            29.375L, 245 - k * 17, 41 + k * 36, 148
        };
        const ScreenVertex b{
            636 - k, 28 + k * 5, 0.14L + k * 0.15L, 1.25L, 63.125L,
            -12.625L + k, 76, 238 - k * 11, 29 + k * 19
        };
        const ScreenVertex c{
            (layer & 1) ? 4 + k : 616 - k * 7,
            478 - k, 0.53L + k * 0.035L, 0.875L, -14.375L - k * 2,
            10.75L - k * 5, 39 + k * 54, 114, 247 - k * 21
        };
        const auto triangle = setup_triangle({a, b, c}, state);
        if (!triangle || triangle->source)
            throw std::runtime_error("expected a wide prepared triangle");
        const auto bounds = triangle->bounds;
        const int start_tx = bounds.x0 / tile_size, end_tx = (bounds.x1 - 1) / tile_size;
        const int start_ty = bounds.y0 / tile_size, end_ty = (bounds.y1 - 1) / tile_size;
        for (int tx = start_tx; tx <= end_tx; ++tx) {
            const int off = std::max(0, tx * tile_size - bounds.x0);
            fixture.max_x_offset = std::max(fixture.max_x_offset, off);
            fixture.x_residues |= 1u << (off & 3);
        }
        for (int ty = start_ty; ty <= end_ty; ++ty) {
            const int off = std::max(0, ty * tile_size - bounds.y0);
            fixture.max_y_offset = std::max(fixture.max_y_offset, off);
            fixture.y_residues |= 1u << (off & 3);
        }
        pass.primitives.push_back(*triangle);
    }
    if (fixture.max_x_offset < 560 || fixture.max_y_offset < 400 ||
        fixture.x_residues != 15 || fixture.y_residues != 15)
        throw std::runtime_error("wide prepared triangle fixture lost long offsets or step residues");
    return fixture;
}

} // namespace

int main(int argc, char** argv) {
    try {
        if (argc != 5) throw std::invalid_argument("CASE IDLE_CYCLES OUTPUT.json PACKETS.bin");
        const std::string name = argv[1];
        const auto idle = std::stoull(argv[2]);
        Simulation sim(""); Renderer oracle; std::uint32_t sequence = 1;
        const auto ui_primitives = [] {
            std::vector<Primitive> result;
            result.push_back(Rect{{0, 0, 640, 480}, overlay_state({16, 24, 48}), 0});
            result.push_back(Rect{{0, 0, 640, 24}, overlay_state({40, 80, 160}), 0});
            result.push_back(Rect{{8, 32, 632, 440}, overlay_state({220, 220, 220}), 0});
            for (int row = 0; row < 32; ++row) {
                const int y = 36 + row * 12;
                if (row % 2) result.push_back(Rect{{10, y, 630, y + 12}, overlay_state({200, 200, 210}), 0});
                for (int word = 0; word < 4; ++word) {
                    const int x = 16 + word * 150 + (row * 7) % 30;
                    result.push_back(Rect{{x, y + 2, x + 40 + (row * 13 + word * 17) % 80, y + 10},
                                          overlay_state({20, 20, 20}), 0});
                }
            }
            result.push_back(Rect{{0, 448, 640, 480}, overlay_state({40, 80, 160}), 0});
            return result;
        };
        std::uint64_t seed_cycles = 0;
        if (name == "mixed-depth-scissor") {
            // Different neighboring D24 values including exact comparison equality.
            // Single-column rectangles exercise normal GPU writes but never pair.
            Pass seed;
            seed.target = 1;
            seed.clear_color = 0x5b6d;
            std::uint32_t depth_values[] = {0x00302019u, 0x008060d1u, 0x00504087u};
            auto state = RenderState{};
            state.color_write = false;
            state.depth_test = false;
            for (int x : {25, 626}) {
                const int end = x == 25 ? 43 : 640;
                for (int column = x; column < end; ++column) {
                    seed.primitives.push_back(Rect{{column, 27, column + 1, 73}, state,
                                                   depth_values[column % 3]});
                }
            }
            const auto precondition = hw::compile_pass(seed, sequence);
            sim.render(precondition);
            seed_cycles = sim.last_submission_cycles;
            sequence = precondition.next_sequence;
            oracle.render(seed, RenderMode::Monolithic);
            sim.compare(oracle);
        } else if (name == "dirty-skip") {
            Bounds previous_bounds;
            const auto previous = icosahedron_pass(0.42f, 0.75f, 0.18f, previous_bounds);
            const auto precondition = hw::compile_pass(previous, sequence);
            sim.render(precondition);
            seed_cycles = sim.last_submission_cycles;
            sequence = precondition.next_sequence;
            oracle.render(previous, RenderMode::Monolithic);
            sim.compare(oracle);
        }
        hw::HostPassCompiler texture_compiler;
        std::shared_ptr<const Image> locality_texture;
        std::uint64_t seed_texture_bytes = 0;
        if (name == "texture-refill-stress" || name == "texture-refill-resident")
            locality_texture = patterned_texture(128, 128, 260, 0x1a7c);
        else if (name == "texture-hit-control")
            locality_texture = patterned_texture(8, 8, 16, 0x1a7c);
        if (name == "texture-refill-resident") {
            // The offscreen sprite binds and uploads the asset but produces no
            // tile references. An ordinary successful fence commits residency.
            Pass seed;
            seed.target = 1;
            seed.color_load = LoadOp::Load;
            seed.depth_load = LoadOp::Load;
            auto state = overlay_state();
            state.texture = locality_texture;
            state.shade = ShadeMode::TextureReplace;
            seed.primitives.emplace_back(Sprite{{640, 480, 641, 481}, 0, 0, state, 0});
            const auto upload = texture_compiler.compile(seed, sequence);
            if (upload.reference_count != 0 || upload.texture_upload_bytes == 0)
                throw std::runtime_error("resident seed must upload once and issue no texture samples");
            sim.render(upload);
            seed_cycles = sim.last_submission_cycles;
            seed_texture_bytes = upload.texture_upload_bytes;
            sequence = upload.next_sequence;
            texture_compiler.complete();
            oracle.render(seed, RenderMode::Monolithic);
            sim.compare(oracle);
        }
        for (std::uint64_t n = 0; n < idle; ++n) sim.tick();
        hw::HostProgram program;
        Pass expected;
        OffsetWorkload offset_fixture;
        if (name == "prepared-wide-offsets") {
            offset_fixture = wide_offset_triangles();
            expected = std::move(offset_fixture.pass);
            program = texture_compiler.compile(expected, sequence);
            if (program.texture_upload_bytes != 576 || program.resident_texture_bytes != 576)
                throw std::runtime_error("expected one first-use atlas shared by the four prepared records");
        } else if (name == "texture-split-pitch") {
            expected = split_texture_pass();
            program = texture_compiler.compile(expected, sequence);
            if (program.texture_upload_bytes != 348)
                throw std::runtime_error("split pitch case changed its packed texture extents");
        } else if (locality_texture) {
            expected = locality_texture_pass(locality_texture);
            program = texture_compiler.compile(expected, sequence);
            const auto bytes = static_cast<std::uint64_t>(locality_texture->pitch_bytes()) *
                locality_texture->height();
            if (program.resident_texture_bytes != bytes ||
                program.texture_upload_bytes != (seed_texture_bytes ? 0 : bytes))
                throw std::runtime_error("texture workload lost its declared upload/residency path");
        } else if (name == "ico") {
            Bounds box{}; expected = icosahedron_pass(0.42f, 0.75f, 0.18f, box);
            program = hw::compile_pass(expected, sequence);
        } else if (name == "ui-store" || name == "ui-discard" ||
                   name == "ui-load" || name == "pointer") {
            expected.target = 1;
            expected.primitives = ui_primitives();
            if (name == "ui-discard") expected.depth_store = StoreOp::Discard;
            if (name == "ui-load" || name == "pointer") {
                expected.color_load = LoadOp::Load; expected.depth_load = LoadOp::Load;
            }
            if (name == "pointer") expected.primitives = {
                Rect{{300, 200, 306, 209}, overlay_state({255, 255, 255}), 0}};
            program = hw::compile_pass(expected, sequence);
        } else if (name == "mixed-depth-scissor") {
            expected.target = 1;
            expected.color_load = LoadOp::Load;
            expected.depth_load = LoadOp::Load;
            // The first box starts odd, spans x=31/32 and ends odd. The second
            // reaches the right edge and ends even. Both cross y=31/32 and 63/64.
            const Bounds boxes[] = {{25, 27, 43, 73}, {626, 27, 640, 73}};
            const std::uint32_t depth = 0x00504087u;
            for (const auto box : boxes) {
                RenderState state;
                state.scissor = box;
                state.color = {31, 151, 97};
                state.depth_func = DepthFunc::Less;
                state.depth_write = false;
                expected.primitives.push_back(Rect{{box.x0 - 2, 24, box.x1 + 2, 36}, state, depth});
                state.color_write = false;
                state.depth_write = true;
                state.depth_func = DepthFunc::LessEqual;
                expected.primitives.push_back(Rect{{box.x0 - 2, 36, box.x1 + 2, 48}, state, depth});
                state.color = {251, 71, 27};
                state.color_write = true;
                state.depth_func = DepthFunc::LessEqual;
                expected.primitives.push_back(Rect{{box.x0 - 2, 48, box.x1 + 2, 61}, state, depth});
                state.depth_func = DepthFunc::Always;
                expected.primitives.push_back(Rect{{box.x0 - 2, 61, box.x1 + 2, 76}, state, depth});
            }
            program = hw::compile_pass(expected, sequence);
        } else if (name == "dirty-skip") {
            Bounds previous_bounds, next_bounds;
            (void)icosahedron_pass(0.42f, 0.75f, 0.18f, previous_bounds);
            expected = icosahedron_pass(0.62f, 0.95f, 0.30f, next_bounds);
            expected.skip_empty_tiles = true;
            auto marker = overlay_state({0, 0, 0});
            marker.scissor = {0, 0, 0, 0};
            expected.primitives.push_back(Rect{previous_bounds, marker, 0});
            program = hw::compile_pass(expected, sequence);
        } else if (name == "empty-load" || name == "empty-load-discard") {
            expected.target = 1;
            expected.color_load = LoadOp::Load;
            expected.depth_load = LoadOp::Load;
            if (name == "empty-load-discard") expected.depth_store = StoreOp::Discard;
            program = hw::compile_pass(expected, sequence);
        } else if (name == "empty-discard") {
            expected.target = 1;
            expected.depth_store = StoreOp::Discard;
            program = hw::compile_pass(expected, sequence);
        } else if (name == "copy") {
            hw::CopyCommand copy;
            copy.source = 0; copy.target = 1; copy.width = 640; copy.height = 480;
            program.bytes = hw::encode_packet(hw::Opcode::CopyRect, sequence++, hw::encode_copy_command(copy));
            std::vector<std::uint8_t> token(4); hw::write_u32(token, 0, 0xbe7c);
            program.fence_token = 0xbe7c; program.fence_sequence = sequence;
            const auto fence = hw::encode_packet(hw::Opcode::Fence, sequence, token);
            program.bytes.insert(program.bytes.end(), fence.begin(), fence.end());
        } else if (name == "ico-flat") {
            // A flat icosahedron as kind-4 records: the setup's own orientation
            // and back-face culling replace the CPU's.
            Bounds box{};
            const auto gouraud = icosahedron_pass(0.42f, 0.75f, 0.18f, box);
            std::vector<std::pair<VertexSource, RenderState>> faces;
            for (const auto& primitive : gouraud.primitives) {
                const auto& t = std::get<Triangle>(primitive);
                VertexSource source; source.cull_negative = true;
                source.bounds = vertex_bounds(t.snapped);
                for (unsigned k = 0; k < 3; ++k) {
                    source.points[k] = t.snapped[k];
                    // The Gouraud plane's depth near each vertex, as D24*256.
                    const int px = std::clamp(t.snapped[k].x / 16, t.bounds.x0, t.bounds.x1 - 1);
                    const int py = std::clamp(t.snapped[k].y / 16, t.bounds.y0, t.bounds.y1 - 1);
                    source.depth[k] = depth_code(t.z.at(px - t.bounds.x0, py - t.bounds.y0)) << 8;
                }
                // Submit every other face reversed: culling must drop exactly those.
                faces.push_back({source, overlay_state({200, 120, 40})});
                faces.back().second.depth_test = faces.back().second.depth_write = true;
                std::swap(source.points[1], source.points[2]); std::swap(source.depth[1], source.depth[2]);
                faces.push_back({source, faces.back().second});
            }
            Pass descriptor; descriptor.target = 1; descriptor.depth_store = StoreOp::Discard;
            auto vertex = vertex_pass(faces, descriptor, 0, sequence);
            program = std::move(vertex.program); expected = std::move(vertex.oracle);
        } else if (name == "closeup") {
            auto faces = sphere_triangles(1, 300.0f, 250.0f, 230.0f, 2.2f);
            const auto back = sphere_triangles(2, 470.0f, 210.0f, 160.0f, 4.0f);
            faces.insert(faces.end(), back.begin(), back.end());
            Pass descriptor; descriptor.target = 1; descriptor.depth_store = StoreOp::Discard;
            auto vertex = vertex_pass(faces, descriptor, 0, sequence);
            program = std::move(vertex.program); expected = std::move(vertex.oracle);
        } else if (name == "vertex0" || name == "vertex1") {
            const int margin = name == "vertex0" ? 0 : 1;
            Pass descriptor; descriptor.target = 1; descriptor.clear_color = 0x18e3;
            auto vertex = vertex_pass(vertex_triangles(margin + 11, 400), descriptor, margin, sequence);
            program = std::move(vertex.program); expected = std::move(vertex.oracle);
        } else {
            const auto scene = name == "showcase" ? DemoScene::Showcase : name == "perspective" ? DemoScene::Perspective :
                name == "overdraw" ? DemoScene::Overdraw : DemoScene::Opaque;
            if (name != "showcase" && name != "perspective" && name != "overdraw" && name != "opaque")
                throw std::invalid_argument("unknown isolated case");
            expected = make_demo_pass(scene, 1, 1.2L); program = hw::compile_pass(expected, sequence);
        }
        const auto start = sim.cycles;
        const auto initial_x = sim.dut.video_x, initial_y = sim.dut.video_y;
        const auto initial_memory = sim.memory.statistics();
        sim.profiling = true;
        sim.render(program);
        sim.profiling = false;
        const auto final_memory = sim.memory.statistics();
        std::ofstream packet_log(argv[4], std::ios::binary);
        packet_log.write(reinterpret_cast<const char*>(program.bytes.data()), program.bytes.size());
        if (!packet_log) throw std::runtime_error("cannot write timed packet stream");
        if (name == "copy") oracle.copy_rect(0, 1, {0, 0}, {0, 0}, 640, 480, RenderMode::Monolithic);
        else oracle.render(expected, RenderMode::Monolithic);
        sim.compare(oracle);
        const auto underflows = sim.scanout_underflows();
        if (underflows) throw std::runtime_error("isolated benchmark scanout underflow");
        std::ofstream out(argv[3]);
        if (!out) throw std::runtime_error("cannot open isolated report");
        out << "{\"case\":\"" << name << "\",\"idle_cycles\":" << idle
            << ",\"initial_core_cycle\":" << start << ",\"initial_video_x\":" << unsigned(initial_x)
            << ",\"initial_video_y\":" << unsigned(initial_y)
            << ",\"seed_cycles\":" << seed_cycles
            << ",\"initial_sdram_refreshes\":" << initial_memory.refreshes
            << ",\"initial_sdram_reads\":" << initial_memory.read_commands
            << ",\"initial_sdram_writes\":" << initial_memory.write_commands
            << ",\"submit_sdram_refreshes\":" << final_memory.refreshes - initial_memory.refreshes
            << ",\"submit_sdram_reads\":" << final_memory.read_commands - initial_memory.read_commands
            << ",\"submit_sdram_writes\":" << final_memory.write_commands - initial_memory.write_commands
            << ",\"offset_x_clocks\":" << sim.tile_states[7]
            << ",\"offset_y_clocks\":" << sim.tile_states[6]
            << ",\"max_requested_offset_x\":" << offset_fixture.max_x_offset
            << ",\"max_requested_offset_y\":" << offset_fixture.max_y_offset
            << ",\"offset_x_residues\":" << offset_fixture.x_residues
            << ",\"offset_y_residues\":" << offset_fixture.y_residues
            << ",\"raster_covered_cycles\":" << sim.raster_cycles[0]
            << ",\"raster_empty_cycles\":" << sim.raster_cycles[1]
            << ",\"raster_texture_stall_cycles\":" << sim.raster_cycles[2]
            << ",\"seed_texture_bytes\":" << seed_texture_bytes
            << ",\"timed_texture_upload_bytes\":" << program.texture_upload_bytes
            << ",\"resident_texture_bytes\":" << program.resident_texture_bytes
            << ",\"submitted_bytes\":" << program.bytes.size()
            << ",\"core_cycles\":" << sim.last_submission_cycles
            << ",\"oracle_checked\":true,\"scanout_underflows\":" << underflows << "}\n";
        std::cout << name << " delay=" << idle << " cycles=" << sim.last_submission_cycles << '\n';
        return 0;
    } catch (const std::exception& error) { std::cerr << error.what() << '\n'; return 1; }
}

matched.runner:
"""Run and compare exact-start triangle-offset trials against fresh RTL objects."""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess

RUN = Path(__file__).resolve().parent
WORKTREE = RUN.parent / "worktree"
INCLUDE = RUN.parents[2] / ".deps/rtl/oss-cad-suite/share/verilator/include"
DRIVER = RUN / "triangle-offset-matched.cpp"
SCENES = (
    "prepared-wide-offsets",
    "texture-refill-stress", "texture-refill-resident", "texture-hit-control", "texture-split-pitch",
    "ui-store", "ui-discard", "ui-load", "mixed-depth-scissor", "pointer",
    "showcase", "perspective", "overdraw", "opaque", "copy", "ico", "ico-flat",
    "closeup", "vertex0", "vertex1", "empty-discard", "empty-load",
    "empty-load-discard", "dirty-skip",
)
EXACT_CONTROLS = frozenset((
    "ui-store", "ui-discard", "ui-load", "mixed-depth-scissor", "pointer",
    "texture-split-pitch", "copy", "ico-flat", "closeup", "vertex0", "vertex1",
    "empty-discard", "empty-load", "empty-load-discard",
))
OFFSETS = (0, 700000)
MATCHED_FIELDS = (
    "case", "idle_cycles", "initial_core_cycle", "initial_video_x",
    "initial_video_y", "seed_cycles", "initial_sdram_refreshes",
    "initial_sdram_reads", "initial_sdram_writes", "submitted_bytes",
    "packet_sha256", "seed_texture_bytes", "timed_texture_upload_bytes", "resident_texture_bytes",
    "max_requested_offset_x", "max_requested_offset_y", "offset_x_residues", "offset_y_residues",
)


def load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write(path, report):
    path.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8", newline="\n")


def verify_sources(tree, build):
    if not build["board_core_profile"] or build["cpp_device_backends_linked"]:
        raise RuntimeError(f"Expected the board-profile Verilator core in {tree}")
    for path, expected in build["source_sha256"].items():
        if digest(tree / path) != expected:
            raise RuntimeError(f"Source differs from built revision: {tree / path}")
    standard_exe = tree / "build/nano-gpu-tang20k-sim.exe"
    if digest(standard_exe) != build["executable_sha256"]:
        raise RuntimeError(f"Standard benchmark executable differs from report: {standard_exe}")


def measure(args, scenes, offsets):
    tree = RUN / "baseline" if args.mode == "before" else WORKTREE
    model = tree / "build/tang20k-core-sim"
    build = load(model / "build-report.json")
    verify_sources(tree, build)
    obj = model / "obj"
    modules = (
        "setup", "renderer", "demo", "hw_protocol", "sdram_model",
        "verilated", "verilated_dpi", "verilated_vcd_c", "verilated_threads",
    )
    objects = [obj / f"{name}.o" for name in modules] + [obj / "Vnano_gpu_core__ALL.a"]
    inputs = {path: digest(path) for path in [DRIVER, *objects]}
    flags = [
        "-std=c++17", "-O2", "-pthread", "-DVL_TIME_CONTEXT=1",
        "-DNANO_GPU_ORACLE_ONLY=1", "-DNANO_GPU_BOARD_PROFILE=1",
        "-DVM_TRACE=1", "-DVM_TRACE_VCD=1", "-DVM_TRACE_FST=0",
    ]
    includes = (obj, INCLUDE, INCLUDE / "vltstd", tree / "reference/include", tree / "reference/rtl")
    report_dir = RUN / f"{args.mode}-{args.tag}-offsets"
    report_dir.mkdir(exist_ok=True)
    exe = report_dir / "triangle-offset-matched.exe"
    subprocess.run(
        [args.compiler, *flags, *(f"-I{path}" for path in includes),
         str(DRIVER), *map(str, objects), "-o", str(exe)],
        cwd=tree, check=True,
    )
    cases = []
    for scene in scenes:
        for offset in offsets:
            result = report_dir / f"{scene}-{offset}.json"
            packets = report_dir / f"{scene}-{offset}.bin"
            subprocess.run([str(exe), scene, str(offset), str(result), str(packets)],
                           cwd=tree, check=True)
            row = load(result)
            if row["submitted_bytes"] != packets.stat().st_size:
                raise RuntimeError(f"Packet stream length mismatch: {packets}")
            row["packet_sha256"] = digest(packets)
            cases.append(row)
    verify_sources(tree, build)
    if any(digest(path) != expected for path, expected in inputs.items()):
        raise RuntimeError("Linked object archive or benchmark driver changed during measurements")
    head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=tree, text=True).strip()
    write(report_dir / "summary.json", {
        "commit_at_build": head, "build": build, "driver_sha256": inputs[DRIVER],
        "isolated_exe_sha256": digest(exe),
        "linked_object_sha256": {path.relative_to(model).as_posix(): inputs[path] for path in objects},
        "scenes": scenes, "offsets": offsets, "cases": cases,
    })


def compare_continuous(before_path, after_path):
    before, after = map(load, (before_path, after_path))
    if before["clock_hz"] != after["clock_hz"] or before["clock_hz"] != 50_400_000:
        raise RuntimeError("Continuous benchmark clock mismatch")
    if before["scanout_underflows"] or after["scanout_underflows"]:
        raise RuntimeError("Continuous benchmark had scanout underflows")
    cumulative_before = cumulative_after = 0
    results = []
    for old, new in zip(before["cases"], after["cases"], strict=True):
        if old["case"] != new["case"]:
            raise RuntimeError(f"Continuous benchmark case mismatch: {old} versus {new}")
        cumulative_before += old["core_cycles"]
        cumulative_after += new["core_cycles"]
        results.append({
            "case": old["case"], "before": old["core_cycles"], "after": new["core_cycles"],
            "before_cumulative": cumulative_before, "after_cumulative": cumulative_after,
            "cycle_reduction_percent": 100 * (1 - new["core_cycles"] / old["core_cycles"]),
        })
    return {
        "before": cumulative_before, "after": cumulative_after, "cases": results,
        "release_gate": "No cumulative fence delay. Retain individual increases and interpret using matched starts.",
        "cumulative_fences_no_later": all(row["after_cumulative"] <= row["before_cumulative"] for row in results),
    }


def compare(args, scenes, offsets):
    before, after = (load(RUN / f"{label}-{args.tag}-offsets/summary.json") for label in ("before", "after"))
    for report in (before, after):
        if report["scenes"] != list(scenes) or report["offsets"] != list(offsets):
            raise RuntimeError("Comparison selectors differ from measurement selectors")
    if before["driver_sha256"] != after["driver_sha256"] or before["driver_sha256"] != digest(DRIVER):
        raise RuntimeError("Matched runs used different workload drivers")
    comparisons = []
    regressions = []
    exact_control_changes = []
    for (expected_scene, offset), old, new in zip(
        ((scene, offset) for scene in scenes for offset in offsets),
        before["cases"], after["cases"], strict=True,
    ):
        if (old["case"], old["idle_cycles"]) != (expected_scene, offset):
            raise RuntimeError("Report changed executed case order")
        for field in MATCHED_FIELDS:
            if old[field] != new[field]:
                raise RuntimeError(f"{expected_scene} offset {offset}: unmatched {field}: {old[field]} vs {new[field]}")
        if not old["oracle_checked"] or not new["oracle_checked"]:
            raise RuntimeError(f"No full oracle comparison: {expected_scene} offset {offset}")
        if old["scanout_underflows"] or new["scanout_underflows"]:
            raise RuntimeError(f"Scanout underflow: {expected_scene} offset {offset}")
        reduction = 100 * (1 - new["core_cycles"] / old["core_cycles"])
        row = {"before": old, "after": new, "cycle_reduction_percent": reduction}
        comparisons.append(row)
        if new["core_cycles"] > old["core_cycles"]:
            regressions.append(row)
        if expected_scene in EXACT_CONTROLS and new["core_cycles"] != old["core_cycles"]:
            exact_control_changes.append(row)
        old_offsets = old["offset_x_clocks"] + old["offset_y_clocks"]
        new_offsets = new["offset_x_clocks"] + new["offset_y_clocks"]
        print(f"{expected_scene:23} {offset:8}  {old['core_cycles']:9} -> {new['core_cycles']:<9}"
              f"  {reduction:+8.4f}%   offset clocks {old_offsets} -> {new_offsets}")
    summary = {
        "matched": comparisons, "matched_regressions": regressions, "pure_control_changes": exact_control_changes,
        "before_report": before, "after_report": after,
    }
    if args.continuous:
        summary["continuous"] = compare_continuous(*args.continuous)
    write(RUN / f"triangle-offset-{args.tag}-comparison.json", summary)
    if regressions or exact_control_changes:
        raise RuntimeError("A matched-start regression or unaffected-control change merits investigation; see comparison")
    if args.continuous and not summary["continuous"]["cumulative_fences_no_later"]:
        raise RuntimeError("A cumulative continuous fence was later; see comparison")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("before", "after", "compare"))
    parser.add_argument("--case", dest="scenes", choices=SCENES, action="append")
    parser.add_argument("--offset", dest="offsets", type=int, action="append")
    parser.add_argument("--tag", default="full", choices=("full", "pilot", "phase-audit"))
    parser.add_argument("--compiler", default="C:/msys64/ucrt64/bin/g++.exe")
    parser.add_argument("--continuous", type=Path, nargs=2, metavar=("BEFORE_JSON", "AFTER_JSON"))
    args = parser.parse_args()
    scenes = tuple(args.scenes or SCENES)
    offsets = tuple(args.offsets or OFFSETS)
    if min(offsets) < 0 or len(set(offsets)) != len(offsets) or len(set(scenes)) != len(scenes):
        parser.error("Select unique cases and unique nonnegative idle offsets")
    if args.mode == "compare":
        compare(args, scenes, offsets)
    else:
        measure(args, scenes, offsets)


if __name__ == "__main__":
    main()

