// Compare prepared frame B after actual prepared frame A, using naturally
// identical quiescent scanout/SDRAM phase without injecting or resetting state.
#define main original_gpu_main
#include "main.cpp"
#undef main

namespace {

Pass rebase_seed_by_tile(const Pass& source) {
    // Replay the exact prior triangles with one coefficient anchor per tile.
    // This makes seed timing independent of the changed offset pipeline,
    // without modifying its coverage, interpolation or attachment data.
    Pass result = source;
    result.primitives.clear();
    const auto bins = bin_primitives(source.primitives);
    for (int tile = 0; tile < tile_count; ++tile) {
        const int x = (tile % tile_columns) * tile_size;
        const int y = (tile / tile_columns) * tile_size;
        const Bounds tile_bounds{x, y, x + tile_size, y + tile_size};
        for (const auto index : bins[tile]) {
            auto copy = std::get<Triangle>(source.primitives.at(index));
            const auto old = copy.bounds;
            copy.bounds = intersect(old, tile_bounds);
            copy.state.scissor = intersect(copy.state.scissor, tile_bounds);
            for (const auto member : {&Triangle::z, &Triangle::r, &Triangle::g, &Triangle::b,
                                      &Triangle::q, &Triangle::u, &Triangle::v}) {
                auto& plane = copy.*member;
                plane.seed = plane.at(copy.bounds.x0 - old.x0, copy.bounds.y0 - old.y0);
            }
            result.primitives.push_back(copy);
        }
    }
    return result;
}

std::vector<std::uint64_t> phase_signature(const Simulation& sim) {
    const auto* r = sim.dut.rootp;
    return {
        sim.cycles, sim.dut.video_x, sim.dut.video_y,
        r->nano_gpu_core__DOT__memory_service__DOT__state,
        r->nano_gpu_core__DOT__memory_service__DOT__txn,
        r->nano_gpu_core__DOT__memory_service__DOT__read_stream_active,
        r->nano_gpu_core__DOT__memory_service__DOT__slot_busy,
        r->nano_gpu_core__DOT__memory_service__DOT__bank_open,
        r->nano_gpu_core__DOT__scanout__DOT__in_flight,
        r->nano_gpu_core__DOT__scanout__DOT__request_valid,
        r->nano_gpu_core__DOT__scanout__DOT__horizontal,
        r->nano_gpu_core__DOT__scanout__DOT__vertical,
        r->nano_gpu_core__DOT__memory_service__DOT__refresh_age,
        r->nano_gpu_core__DOT__memory_service__DOT__column_gap,
        r->nano_gpu_core__DOT__memory_service__DOT__turnaround,
        r->nano_gpu_core__DOT__memory_service__DOT__round_robin,
        r->nano_gpu_core__DOT__scanout__DOT__next_fetch,
        r->nano_gpu_core__DOT__scanout__DOT__stored,
        r->nano_gpu_core__DOT__scanout__DOT__read_pointer,
        r->nano_gpu_core__DOT__scanout__DOT__write_pointer,
        r->nano_gpu_core__DOT__scanout__DOT__read_pending,
        r->nano_gpu_core__DOT__scanout__DOT__output_valid,
        r->nano_gpu_core__DOT__scanout__DOT__spare_valid,
        r->nano_gpu_core__DOT__scanout__DOT__frame_ready,
        r->nano_gpu_core__DOT__scanout__DOT__frame_black,
        r->nano_gpu_core__DOT__scanout__DOT__streaming,
        r->nano_gpu_core__DOT__scanout__DOT__seen_front,
    };
}

void write_array(std::ostream& out, const std::vector<std::uint64_t>& values) {
    const char* delimiter = "[";
    for (const auto value : values) {
        out << delimiter << value;
        delimiter = ",";
    }
    out << ']';
}

} // namespace

int main(int argc, char** argv) {
    try {
        if (argc != 6) throw std::invalid_argument("MODE START_CYCLE EXTENT OUT PACKETS");
        const std::string mode = argv[1];
        const auto idle = std::stoull(argv[2]);
        Simulation sim("");
        Renderer oracle;
        Bounds previous_bounds;
        const auto previous = icosahedron_pass(0.42f, 0.75f, 0.18f, previous_bounds);
        const auto local_previous = rebase_seed_by_tile(previous);
        const auto before = hw::compile_pass(local_previous, 1);
        sim.profiling = true;
        sim.render(before);
        sim.profiling = false;
        if (sim.tile_states[6] || sim.tile_states[7])
            throw std::runtime_error("tile-rebased prior frame still used offset walking");
        sim.tile_states.fill(0);
        const auto seed_cycles = sim.last_submission_cycles;
        const auto seed_fence_absolute = sim.cycles;
        oracle.render(previous, RenderMode::Monolithic);
        sim.compare(oracle);
        for (std::uint64_t n = 0; n < idle; ++n) sim.tick();
        std::ofstream out(argv[4]);
        if (!out) throw std::runtime_error("cannot open phase output");
        if (mode != "measure") throw std::invalid_argument("unsupported phase mode");
        Bounds next_bounds;
        auto expected = icosahedron_pass(0.62f, 0.95f, 0.30f, next_bounds);
        expected.skip_empty_tiles = true;
        auto marker = overlay_state({0, 0, 0});
        marker.scissor = {0, 0, 0, 0};
        expected.primitives.push_back(Rect{previous_bounds, marker, 0});
        const auto program = hw::compile_pass(expected, before.next_sequence);
        const auto phase = phase_signature(sim);
        const auto counts = sim.memory.statistics();
        sim.profiling = true;
        sim.render(program);
        sim.profiling = false;
        oracle.render(expected, RenderMode::Monolithic);
        sim.compare(oracle);
        if (sim.scanout_underflows()) throw std::runtime_error("measured phase had underflow");
        std::ofstream packets(argv[5], std::ios::binary);
        packets.write(reinterpret_cast<const char*>(program.bytes.data()), program.bytes.size());
        packets.close();
        if (!packets) throw std::runtime_error("cannot write measured packet stream");
        out << "{\"phase_signature\":";
        write_array(out, phase);
        out << ",\"seed_cycles\":" << seed_cycles
            << ",\"seed_fence_absolute\":" << seed_fence_absolute
            << ",\"seed_idle\":" << idle
            << ",\"seed_sdram_refreshes\":" << counts.refreshes
            << ",\"seed_sdram_reads\":" << counts.read_commands
            << ",\"seed_sdram_writes\":" << counts.write_commands
            << ",\"core_cycles\":" << sim.last_submission_cycles
            << ",\"offset_x_clocks\":" << sim.tile_states[7]
            << ",\"offset_y_clocks\":" << sim.tile_states[6]
            << ",\"submitted_bytes\":" << program.bytes.size()
            << ",\"oracle_checked\":true,\"scanout_underflows\":0}\n";
        out.close();
        if (!out) throw std::runtime_error("cannot write measured phase report");
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

