#pragma once

// Test-only setup counters. Sample the retained coefficients and counters
// before the same rising edge that consumes them in the renderer.
struct TriangleOffsetStats {
    enum { OffsetY = 6, OffsetX = 7 };
    std::array<std::array<std::uint64_t, 1024>, 2> lengths{};
    std::array<std::array<std::uint64_t, 128>, 2> plane_masks{};
    std::array<std::array<std::uint64_t, 5>, 2> shade_histogram{};
    std::array<std::uint64_t, 2> clocks{}, zero_slope_axes{}, zero_slope_skip_clocks{};
    // Available when the entire participating slope for each plane fits.
    static constexpr std::array<unsigned, 4> examined_widths{33, 37, 41, 45};
    std::array<std::array<std::uint64_t, examined_widths.size()>, 2> signed_fit_axes{}, signed_fit_savings{};
    std::uint64_t ideal_edge_overlap = 0;
    unsigned previous_state = 0;

    void sample(const Vnano_gpu_core___024root& top) {
        const auto state = top.nano_gpu_core__DOT__tile_renderer__DOT__state;
        const auto previous = previous_state;
        previous_state = state;
        if (state != OffsetX && state != OffsetY) return;
        const auto axis = state == OffsetX ? 0u : 1u;
        ++clocks[axis];
        if (state == previous) return;
        const unsigned dx = top.nano_gpu_core__DOT__tile_renderer__DOT__offset_x;
        const unsigned dy = top.nano_gpu_core__DOT__tile_renderer__DOT__offset_y;
        const auto count = axis == 0 ? dx : dy;
        if (count == 0 || count > (axis == 0 ? 640u : 480u))
            throw std::logic_error("Unexpected offset count in benchmark");
        ++lengths[axis].at(count);
        const unsigned enable = top.nano_gpu_core__DOT__tile_renderer__DOT__plane_enable;
        const unsigned shade = top.nano_gpu_core__DOT__tile_renderer__DOT__words__BRA__1__KET__ & 0xffu;
        ++plane_masks[axis].at(enable);
        ++shade_histogram[axis].at(shade);
        if (previous != OffsetY && previous != OffsetX)
            ideal_edge_overlap += std::min(9u, dx + dy);

        bool slope_is_zero = true;
        std::array<bool, examined_widths.size()> all_fit{true, true, true, true};
        for (unsigned plane = 0; plane < 7; ++plane) {
            if (!(enable & (1u << plane))) continue;
            const auto slope = top.nano_gpu_core__DOT__tile_renderer__DOT__coefficient_data[plane];
            if (slope != 0) slope_is_zero = false;
            for (unsigned n = 0; n < examined_widths.size(); ++n) {
                const unsigned high_bits = 65 - examined_widths[n];
                const auto high = slope >> (examined_widths[n] - 1);
                const auto all_ones = (std::uint64_t{1} << high_bits) - 1;
                all_fit[n] &= high == 0 || high == all_ones;
            }
        }
        for (unsigned n = 0; n < examined_widths.size(); ++n) {
            if (!all_fit[n]) continue;
            ++signed_fit_axes[axis][n];
            signed_fit_savings[axis][n] += count - count / 4 - count % 4;
        }
        if (slope_is_zero) {
            ++zero_slope_axes[axis];
            zero_slope_skip_clocks[axis] += count - 1;
        }
    }

    std::uint64_t iterations(unsigned axis, unsigned jump) const {
        std::uint64_t total = 0;
        for (unsigned i = 1; i < lengths[axis].size(); ++i)
            total += lengths[axis][i] * (i / jump + i % jump);
        return total;
    }

    void print(std::ostream& out, const char* name, std::uint64_t cycles,
               unsigned active_jump) const {
        for (unsigned axis = 0; axis < 2; ++axis) {
            const auto expected = iterations(axis, 1) - (active_jump == 4 ? signed_fit_savings[axis][0] : 0);
            if (clocks[axis] != expected)
                throw std::logic_error("Profiled offset clocks differ from the exact signed-slope schedule");
        }
        const auto axis_data = [&](unsigned axis) {
            out << "{\"clocks\":" << clocks[axis] << ",\"single_step_clocks\":" << iterations(axis, 1)
                << ",\"fixed_2_clocks\":" << iterations(axis, 2)
                << ",\"fixed_4_clocks\":" << iterations(axis, 4)
                << ",\"fixed_8_clocks\":" << iterations(axis, 8)
                << ",\"zero_slope_axes\":" << zero_slope_axes[axis]
                << ",\"zero_slope_skip_clocks\":" << zero_slope_skip_clocks[axis];
            const auto sparse = [&](const char* key, const auto& values) {
                out << ",\"" << key << "\":{";
                bool first = true;
                for (unsigned i = 0; i < values.size(); ++i) {
                    if (!values[i]) continue;
                    if (!first) out << ',';
                    out << '\"' << i << "\":" << values[i];
                    first = false;
                }
                out << '}';
            };
            out << ",\"fixed4_when_all_enabled_slopes_fit\":{";
            for (unsigned n = 0; n < examined_widths.size(); ++n) {
                if (n != 0) out << ',';
                const auto saved = signed_fit_savings[axis][n];
                out << '\"' << examined_widths[n] << "\":{\"eligible_axes\":" << signed_fit_axes[axis][n]
                    << ",\"saved_offset_clocks\":" << saved
                    << ",\"remaining_offset_clocks\":" << iterations(axis, 1) - saved << '}';
            }
            out << '}';
            sparse("starting_axis_lengths", lengths[axis]);
            sparse("enabled_plane_masks", plane_masks[axis]);
            sparse("shade_modes", shade_histogram[axis]);
            out << '}';
        };
        out << "{\"case\":\"" << name << "\",\"cycles\":" << cycles
            << ",\"ideal_edge_setup_overlap_clocks\":" << ideal_edge_overlap << ",\"x\":";
        axis_data(0);
        out << ",\"y\":";
        axis_data(1);
        out << "}\n";
        out.flush();
    }
};
